import{at as e,it as t,n,vt as r}from"./chunks/framework.BPeR9Rpo.js";var i=JSON.parse(`{"title":"Dashboards","description":"","frontmatter":{"title":"Dashboards","covers":{"screens":["SCR-024","SCR-056"],"stories":["US-055","US-056","US-057","US-058","US-059","US-060","US-062"]}},"headers":[],"relativePath":"usage/dashboards.md","filePath":"usage/dashboards.md"}`),a={name:`usage/dashboards.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="dashboards" tabindex="-1">Dashboards <a class="header-anchor" href="#dashboards" aria-label="Permalink to “Dashboards”">​</a></h1><p>A dashboard gives readers a structured view of the architecture. It arranges <strong>widgets</strong> in a grid of 12 columns: text widgets with formatted notes, table widgets that show the rows of a <a href="./catalogs">catalog</a>, KPI widgets with one figure, and chart widgets with distributions. You need the permission <code>entity:read</code> (for example the role <code>viewer</code>) to see dashboards and to create personal ones; shared dashboards need <code>dashboard:manage</code> (role <code>enterprise-architect</code>).</p><p>There are two kinds of dashboards:</p><ul><li><strong>Shared</strong> dashboards are visible to every reader of the instance. Every person with <code>dashboard:manage</code> can change and delete every shared dashboard.</li><li><strong>Personal</strong> dashboards are visible to you only. Nobody else sees them in a list, and their address answers <em>The dashboard does not exist or you may not see it</em>. The exception are administrators with the permission <code>settings:manage</code>: they see the personal dashboards of other persons in the list, marked with the owner, and can read them, but never change or delete them.</li></ul><p>Service accounts have no access to dashboards.</p><h2 id="the-page-dashboards" tabindex="-1">The page Dashboards <a class="header-anchor" href="#the-page-dashboards" aria-label="Permalink to “The page Dashboards”">​</a></h2><p>Choose <em>Dashboards</em> in the header. The page lists the dashboards you may see with their visibility (<em>Shared</em> or <em>Personal</em>), the owner and the number of widgets. Choose a dashboard to open it.</p><h2 id="create-a-dashboard" tabindex="-1">Create a dashboard <a class="header-anchor" href="#create-a-dashboard" aria-label="Permalink to “Create a dashboard”">​</a></h2><ol><li><p>Choose <em>Create dashboard</em> on the page <em>Dashboards</em>.</p></li><li><p>Fill in the dialog:</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>Name</td><td>required, 1 to 200 characters; unique among the shared dashboards and among your personal dashboards, regardless of upper and lower case</td></tr><tr><td>Description</td><td>optional, up to 1000 characters</td></tr><tr><td>Visibility</td><td><em>Shared</em>: visible to every reader (needs the permission to manage dashboards); <em>Personal</em>: visible to you only</td></tr></tbody></table></li><li><p>Choose <em>Create dashboard</em>. The new dashboard opens with the notice &quot;No widgets yet. Add widget.&quot;</p></li></ol><p>If the name is already taken, the dialog says so. Without the permission to manage dashboards, <em>Shared</em> is not selectable.</p><h2 id="read-a-dashboard" tabindex="-1">Read a dashboard <a class="header-anchor" href="#read-a-dashboard" aria-label="Permalink to “Read a dashboard”">​</a></h2><p>A dashboard shows its widgets at their positions. The data is computed each time you open it, with your own permissions: a table widget shows the catalog as you may see it, including locked columns (see <a href="./../administration/property-visibility">Property visibility</a>). Readers who work in the <a href="./portal#dashboards">portal</a> see the same dashboards there, read-only.</p><ul><li>A <strong>text widget</strong> shows its Markdown as formatted text.</li><li>A <strong>table widget</strong> shows the rows of its catalog, with the columns of its saved view if it has one. Below the table, <em>Page 1 of 5 · 47 entries</em> and the pagination move between pages.</li><li>A <strong>KPI widget</strong> shows one aggregated value with its unit, for example <em>42,000,000 CHF</em>. With a target value it also shows the target, the difference and a trend as icon and text (<em>8,000,000 CHF below the target</em>). Without a value (for example, no entity has a value of the property) it shows <em>– (no data)</em>; counting nothing gives 0. With the comparison <em>Compared with 30 days ago</em> it also shows <em>30 days ago (Oct 20, 2026): 35,000,000 CHF</em> (the date of the value is part of the text), the signed difference with its percentage and a trend as icon and text (<em>Increase: +7,000,000 CHF (+20%)</em>, <em>Decrease: …</em> or <em>Unchanged</em>); the percentage is left out when the value 30 days ago was 0. If no entity had a value then, the KPI shows <em>No comparison value</em>; a count compares with 0.</li><li>A <strong>chart widget</strong> shows one aggregation as bars, lines, areas, pie or donut segments, or a treemap, with legend and data labels if configured. Hover over or focus a group for its value. Names are shown in your language; entities without a value form the group <em>(none)</em>, and only the 50 largest groups are shown, the rest is summed as <em>Other</em>. A table with the same figures is available for screen readers.</li><li>A KPI or chart widget that aggregates a property whose values you may not read for every entity (see <a href="./../administration/property-visibility">Property visibility</a>) shows <em>The values of this property are not readable for every entity, so no aggregate is shown.</em> Roles that may override the visibility do not lift this. Counting entities and grouping by element type or layer are always possible.</li><li>A KPI or chart widget whose element type or property was removed from the metamodel since then shows <em>The widget no longer fits the metamodel. Edit or remove it.</em> The other widgets stay unaffected, and no widget is removed automatically. A deleted architecture layer moves its element types into the group <em>(none)</em>.</li><li>A widget whose catalog is gone or not visible to you shows <em>Catalog not found</em>; a widget whose saved view is gone shows <em>Saved view not found</em>. The other widgets stay unaffected.</li><li>Widgets that overlap are marked with a red border and the note <em>Overlaps another widget</em>.</li></ul><h2 id="change-a-dashboard" tabindex="-1">Change a dashboard <a class="header-anchor" href="#change-a-dashboard" aria-label="Permalink to “Change a dashboard”">​</a></h2><p>If you may change a dashboard, the page has the button <em>Edit</em>. In the edit mode you can:</p><ul><li><strong>Add widget</strong>: choose the type <em>Text</em>, <em>Table</em>, <em>KPI</em> or <em>Chart</em>, enter a title of 1 to 150 characters and configure it (see below). New widgets go below the existing ones and can then be arranged. A dashboard has at most 50 widgets.</li><li><strong>Edit</strong> or <strong>Remove</strong> a widget with the buttons in its header. The type of a widget cannot change; remove it and add a new one.</li><li><strong>Rename</strong> the dashboard, change its description, or <strong>Share with everyone</strong>: a personal dashboard becomes shared, if you hold <code>dashboard:manage</code>, the name is free among the shared dashboards, and no widget shows a personal catalog. A shared dashboard does not become personal again.</li><li><strong>Delete</strong> the dashboard with all its widgets, after a confirmation.</li></ul><p>Choose <em>Done</em> to leave the edit mode.</p><h3 id="text-widgets" tabindex="-1">Text widgets <a class="header-anchor" href="#text-widgets" aria-label="Permalink to “Text widgets”">​</a></h3><p>A text widget holds Markdown of up to 10000 characters, for example methodological notes: bold and italic text, lists, quotes, headings, tables and links. Links work with <code>http</code>, <code>https</code> and <code>mailto</code> only. Raw HTML is not interpreted; it appears as text. Scripts, event handlers and other schemes such as <code>javascript:</code> never run.</p><h3 id="table-widgets" tabindex="-1">Table widgets <a class="header-anchor" href="#table-widgets" aria-label="Permalink to “Table widgets”">​</a></h3><p>A table widget needs a catalog you may see. On a shared dashboard only shared catalogs can be chosen, so that every reader sees data; a personal dashboard can also show your personal catalogs. Optionally choose a saved view of that catalog for its columns, and the rows per page (5 to 100, default 10). The widget always reads current data through the catalog query, as the reader.</p><h3 id="kpi-and-chart-widgets" tabindex="-1">KPI and chart widgets <a class="header-anchor" href="#kpi-and-chart-widgets" aria-label="Permalink to “KPI and chart widgets”">​</a></h3><p>Both aggregate the entities of an <strong>element type</strong>, subtypes included; deleted entities and the changes of solutions are not counted. Choose:</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>Element type</td><td>the element type to aggregate, or <em>All element types</em> for a count of every entity</td></tr><tr><td>Function</td><td><em>Count</em>, <em>Sum</em>, <em>Average</em>, <em>Minimum</em> or <em>Maximum</em>. Sum, average, minimum and maximum need a property of the type number (integer); a count takes the entities themselves or any mapped property and counts the entities that have a value of it</td></tr><tr><td>Property</td><td>the property to aggregate; only properties mapped to the element type are offered</td></tr><tr><td>Unit</td><td>optional, up to 20 characters, shown after the value</td></tr></tbody></table><p>For a <strong>KPI widget</strong>, choose the comparison <em>With a target value</em> and enter the target to see the difference and the trend; or choose <em>Compared with 30 days ago</em> to compare with the value the same aggregation had 30 days before (exactly 30 times 24 hours). That value is computed from the history of the entities: the entities that existed then and were not deleted yet, each with the value of the last version up to then. It uses the current metamodel, so a change of an element type since then (for example its base type) is not reconstructed, and the comparison is approximate in that case. It follows the same visibility rules as the current value: for a property you may not read for every entity, neither value is shown. Charts have no comparison.</p><p>For a <strong>chart widget</strong>, choose <em>Group by</em>: a property (of the type text, selection, yes/no or reference; a reference groups by the name of the referenced entity), the element type, or the architecture layer. Entities of a metatype without a layer form the group <em>(none)</em>. Choose the chart type (<em>Bar</em>, <em>Line</em>, <em>Area</em>, <em>Pie</em>, <em>Donut</em> or <em>Treemap</em>) and whether to show the legend and the data labels. A chart shows one series.</p><p>A new widget starts with all entities counted, and a chart grouped by element type. Changing the element type removes a property or grouping that it does not have. Grouping by the name of the entities is not offered.</p><h2 id="arrange-the-widgets" tabindex="-1">Arrange the widgets <a class="header-anchor" href="#arrange-the-widgets" aria-label="Permalink to “Arrange the widgets”">​</a></h2><p>The grid has 12 columns. A widget has a column, a width, a row and a height:</p><table tabindex="0"><thead><tr><th>Property</th><th>Allowed values</th></tr></thead><tbody><tr><td>Column</td><td>1 to 12</td></tr><tr><td>Width</td><td>1 to 12; column + width is at most 13</td></tr><tr><td>Row</td><td>1 to 500</td></tr><tr><td>Height</td><td>1 to 6 rows</td></tr></tbody></table><p>In the edit mode:</p><ul><li><strong>Drag</strong> a widget by the handle at the left of its title to move it, and drag the corner at the bottom right to resize it.</li><li>Or use the <strong>arrangement buttons</strong> below a widget (move left, right, up, down; one column narrower or wider; one row shorter or taller), or the <strong>arrow keys</strong> on the handle: arrow keys move the widget, with Shift they resize it.</li></ul><p>Every change is saved at once, as one request. If a widget would reach beyond column 12, the page says <em>Widget exceeds the grid width</em> and does not save the position. Overlaps are allowed; the editor marks them.</p><h2 id="changes-by-several-people" tabindex="-1">Changes by several people <a class="header-anchor" href="#changes-by-several-people" aria-label="Permalink to “Changes by several people”">​</a></h2><p>Every change refers to the version of the dashboard you have loaded. If someone else changed the dashboard in the meantime, the page reloads it and says so; repeat your change.</p><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to “API”">​</a></h2><p>The dashboards are available through <code>/dashboards</code> and <code>/views/dashboards</code> (see the <a href="./../api/">API reference</a>):</p><ul><li><code>GET /dashboards</code> and <code>POST /dashboards</code> list and create dashboards; <code>PUT</code> and <code>DELETE /dashboards/{id}</code> change and delete one.</li><li><code>POST /dashboards/{id}/widgets</code>, <code>PUT</code> and <code>DELETE /dashboards/{id}/widgets/{widgetId}</code> change widgets (a KPI or chart widget carries the property <code>aggregation</code> with <code>metatypeId</code>, <code>propertyDefId</code>, <code>function</code> and, for a chart, <code>groupBy</code>), and <code>PUT /dashboards/{id}/layout</code> positions up to 50 widgets in one request. Every write needs the header <code>If-Match</code> with the version that was read (<code>&quot;3&quot;</code>); without it the answer is 428, with another version 412. The answers carry the new version as <code>ETag</code>.</li><li><code>GET /views/dashboards/{id}</code> returns the configuration, <code>GET /views/dashboards/{id}/data</code> the data of all widgets, and <code>GET /views/dashboards/{id}/widgets/{widgetId}/data?page=</code> another page of a table widget (from 0). The data of a KPI widget has <code>value</code> (null without data), <code>target</code> and, with the comparison <code>vs-previous-value</code>, <code>previousValue</code> (null if no entity had a value then) and <code>previousAt</code> (the point in time, 30 days before the request), that of a chart widget <code>series</code> with <code>kind</code>, <code>key</code>, <code>label</code>, <code>labelKey</code> and <code>value</code> per group; a widget that cannot be computed has the status <code>error</code> with the code <code>restricted</code> or <code>invalid-configuration</code>.</li><li>A taken name answers 422 with the problem type <code>urn:oea:problem:dashboard-name-taken</code>; other invalid input answers 422 with <code>invalidFields</code>. The personal dashboard of another person answers 404.</li></ul>`,38)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};